<div class="modal-body"><h5>Comparador de costos</h5><p class="text-muted">El histórico es sólo referencia; no cambia precios ni partidas.</p>
<?php if(empty($comparison['suppliers'])): ?><div class="alert alert-info">No hay costos registrados para este producto.</div><?php else: ?><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Proveedor</th><th>Último costo</th><th>Mejor costo</th><th>Fecha</th><th>Origen</th><th>Referencia</th></tr></thead><tbody><?php foreach($comparison['suppliers'] as $supplier): $last=$supplier['history'][0]; ?><tr><td><?php echo esc($supplier['supplier_name']); ?></td><td><?php echo to_currency($supplier['last_cost']); ?></td><td><?php echo to_currency($supplier['best_cost']); ?></td><td><?php echo $last['date']?esc(format_to_date($last['date'],false)):'-'; ?></td><td><?php echo $last['source_type']==='manual'?'Manual':'Formal'; ?></td><td><?php echo esc($last['document_folio']); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cerrar</button></div>
